            vaultID: lease.vaultId,
            candidateIDs: [firstID, secondID],
            memoryRevision: 14,
            proposalGeneration: 4
        ))
        client.reviewTransportOutcomes = [
            .outcomeUnknown(URLError(.networkConnectionLost)),
        ]
