                            ]],
                            "time": [],
                            "places": [],
                            "relationships": [],
                            "emotions": [],
                            "values": [],
                            "personality": [],
                            "confidence": 0.7,
                            "futureFacetMetadata": "preserved",
                        ],
                    ],
                    "contentHash": "v2-correction-hash",
