        let correctedPrimaryValue = "我在 2016 年从 A 大学计算机专业毕业。"
        let correctedContent: [String: OwnerTruthJSONValue] = [
            try XCTUnwrap(items.last?.primaryField).rawValue: .string(correctedPrimaryValue),
        ]
