            sessionID: recordID("00000000-0000-0000-0000-000000000075"),
            expectedSessionVersion: 1,
            boundary: .cooldown
        )

        let payload = command.backendPayload
        XCTAssertEqual(Set(payload.keys), [
            "commandId",
            "threadId",
            "expectedSessionVersion",
            "boundary",
        ])
