            "safetyProvider": state == .uploadPending ? NSNull() : "local-signature",
            "processingStatus": processingStatus.rawValue,
            "processingGeneration": processingStatus == .notQueued ? 0 : 1,
            "externalProcessingAllowed": command.allowExternalProcessing,
            "retryable": processingStatus == .retryableFailed,
            "failureCode": processingStatus == .retryableFailed ? "providerUnavailable" : NSNull(),
            "derivedSourceId": derivedSourceID?.rawValue.uuidString ?? NSNull(),
            "updatedAt": "2026-08-03T12:00:00Z",
        ]
    }

    private func makeActiveRuntime() throws -> (AccountLeaseRuntime, AccountLease) {
        let runtime = AccountLeaseRuntime(authorityEpoch: "epoch-v1")
        runtime.publish(session: accountSession(
            subjectId: "owner-a",
            vaultId: "vault-a",
            generation: 1,
            generationID: UUID(uuidString: "00000000-0000-0000-0000-000000000101")!
        ))
        return (runtime, try XCTUnwrap(runtime.capture(forSubjectId: "owner-a")))
    }

    private func g02PendingGroupDirectoryURL() -> URL {
        let root = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        ).first ?? FileManager.default.temporaryDirectory
        return root.appendingPathComponent(
            "b4-g02-pending-group-process-restart",
            isDirectory: true
        )
    }

    private func accountSession(
        subjectId: String,
        vaultId: String,
        generation: UInt64,
        generationID: UUID,
        sessionID: String? = nil
    ) -> AccountSession {
        AccountSession(
            subjectId: subjectId,
            vaultId: vaultId,
            sessionId: sessionID ?? "session-\(generation)",
            tokenFamilyId: "family-\(generation)",
            sessionVersion: Int(generation),
            generation: generation,
            generationId: generationID,
            state: .active,
            activatedAt: Date(timeIntervalSince1970: 1_700_000_000)
        )
    }

