        }
        return [
            "schemaVersion": OwnerTruthPersonLifeStory.schemaVersion,
            "algorithmVersion": OwnerTruthPersonLifeStory.algorithmVersion,
            "format": "plainText",
            "state": "ready",
            "title": "我的人生记录",
