    func testRealtimeVoiceRuntimeConfigAcceptsOnlyFutureBackendProxyTicket() throws {
        let providerRoleText = "只使用服务端正式记忆回答。"
        let providerDigest = SHA256.hash(data: Data(providerRoleText.utf8))
        let providerContextHash = "sha256:" + providerDigest.map {
            String(format: "%02x", $0)
        }.joined()
        let json: [String: Any] = [
            "status": "ready",
            "credentialMode": "oneTimeBackendProxyTicket",
            "accessPath": "backendRealtimeProxy",
            "mobileDirectAllowed": false,
            "brokerStatus": "verified",
            "providerReady": true,
            "releaseVisible": true,
            "retryable": true,
            "contractVersion": 7,
            "expiresAt": "2099-01-01T00:00:00Z",
            "echoSession": [
                "productSessionId": "echo_live_stable_001",
                "targetPersonaId": "subject-1",
                "projectionCheckpoint": "checkpoint-7",
                "authorityEpoch": 7,
                "memoryRevision": 12,
                "contextHash": "sha256:context",
                "providerContextHash": providerContextHash,
            ],
            "sessionContext": [
                "systemRole": "只使用正式记忆",
                "speakingStyle": "自然、温柔",
                "providerRoleText": providerRoleText,
                "providerContextHash": providerContextHash,
                "formalMemorySnapshot": [
                    "schemaVersion": "formal-memory-conversation-v3",
                    "projectionCheckpoint": "checkpoint-7",
                    "authorityEpoch": 7,
                    "memoryRevision": 12,
                    "contextHash": "sha256:context",
                    "providerRoleText": providerRoleText,
                    "providerContextHash": providerContextHash,
                    "coreFacts": [],
                    "coverage": [
                        "eligibleFactCount": 0,
                        "omittedFactCount": 0,
                    ],
                ],
            ],
            "proxy": [
                "address": "wss://api.example.test",
                "uri": "/voice/realtime-stream",
                "sessionToken": "djv_one_time_test_ticket",
                "sessionHeader": "X-DreamJourney-Voice-Session",
                "sdkClientID": "dreamjourney-realtime-proxy",
                "sdkClientKey": "proxy-session",
                "sdkResourceID": "dreamjourney.realtime.proxy",
                "uid": "dju_test",
            ],
        ]

        let config = try XCTUnwrap(RealtimeVoiceRuntimeConfig(json: json))

        XCTAssertFalse(config.isBlocked)
        XCTAssertFalse(config.mobileDirectAllowed)
        XCTAssertEqual(config.proxyAddress, "wss://api.example.test")
        XCTAssertEqual(config.sessionHeader, "X-DreamJourney-Voice-Session")
        XCTAssertEqual(config.productSessionID, "echo_live_stable_001")
        XCTAssertEqual(config.projectionCheckpoint, "checkpoint-7")
        XCTAssertEqual(config.authorityEpoch, 7)
        XCTAssertEqual(config.systemRole, "只使用正式记忆")
        XCTAssertEqual(config.formalMemorySnapshot?["projectionCheckpoint"] as? String, "checkpoint-7")

        var mismatchedSnapshot = json
        var sessionContext = try XCTUnwrap(
            mismatchedSnapshot["sessionContext"] as? [String: Any]
        )
        var snapshot = try XCTUnwrap(
            sessionContext["formalMemorySnapshot"] as? [String: Any]
        )
        snapshot["contextHash"] = "sha256:stale"
        sessionContext["formalMemorySnapshot"] = snapshot
        mismatchedSnapshot["sessionContext"] = sessionContext
        XCTAssertTrue(try XCTUnwrap(RealtimeVoiceRuntimeConfig(json: mismatchedSnapshot)).isBlocked)
    }

    func testRealtimeVoiceRuntimeConfigFailsClosedForDirectExpiredOrIncompleteContract() throws {
        var json: [String: Any] = [
            "status": "ready",
            "credentialMode": "oneTimeBackendProxyTicket",
            "accessPath": "backendRealtimeProxy",
            "mobileDirectAllowed": true,
            "brokerStatus": "verified",
            "providerReady": true,
            "releaseVisible": true,
            "retryable": true,
            "contractVersion": 5,
            "expiresAt": "2099-01-01T00:00:00Z",
            "proxy": [
                "address": "wss://api.example.test",
                "uri": "/voice/realtime-stream",
                "sessionToken": "djv_one_time_test_ticket",
                "sessionHeader": "X-DreamJourney-Voice-Session",
                "sdkClientID": "dreamjourney-realtime-proxy",
                "sdkClientKey": "proxy-session",
                "sdkResourceID": "dreamjourney.realtime.proxy",
                "uid": "dju_test",
            ],
        ]
        XCTAssertTrue(try XCTUnwrap(RealtimeVoiceRuntimeConfig(json: json)).isBlocked)

        json["mobileDirectAllowed"] = false
        json["expiresAt"] = "2020-01-01T00:00:00Z"
        XCTAssertTrue(try XCTUnwrap(RealtimeVoiceRuntimeConfig(json: json)).isBlocked)

        json["expiresAt"] = "2099-01-01T00:00:00Z"
        json["contractVersion"] = 3
        XCTAssertTrue(try XCTUnwrap(RealtimeVoiceRuntimeConfig(json: json)).isBlocked)
    }

