    func testAccountDataExportRemainsDefaultOffAndFailsClosedWithoutServerPolicy() {
        XCTAssertFalse(FeatureFlagService.shared.isEnabled(.accountDataExport))
        let evaluator = FeatureGateEvaluator()
        let unavailablePolicy = FeatureGatePolicySnapshot.unavailable(
            accessMode: .deny,
            reason: "releasePolicyMissing"
        )
        let releaseDecision = evaluator.capture(
            feature: .accountDataExport,
            risk: .ownerTextCore,
            purpose: .route,
            localEnabled: true,
            qaSyntheticOverride: false,
            accountGeneration: "owner-a:1",
            policy: unavailablePolicy
        )
        XCTAssertFalse(releaseDecision.allowed)
        XCTAssertEqual(releaseDecision.reason, "releasePolicyMissing")

        let qaRoute = evaluator.capture(
            feature: .accountDataExport,
            risk: .ownerTextCore,
            purpose: .route,
            localEnabled: true,
            qaSyntheticOverride: true,
            accountGeneration: "owner-a:1",
            policy: unavailablePolicy
        )
        XCTAssertTrue(qaRoute.allowed)
        let requestDecision = evaluator.revalidateForRequest(
            captured: qaRoute,
            localEnabled: true,
            accountGeneration: "owner-a:1",
            currentPolicy: unavailablePolicy
        )
        XCTAssertFalse(requestDecision.allowed)
        XCTAssertEqual(requestDecision.reason, "releasePolicyMissing")
    }

    func testOwnerTruthMediaTaskPresentationKeepsUploadAndProcessingFailuresDistinct() {
        let sourceObjectID = UUID(uuidString: "00000000-0000-0000-0000-000000000b40")!
        let uploadFailure = OwnerTruthMediaTaskPresentation(
            mediaKind: .image,
            fileName: "summer.jpg",
            phase: .uploadRetryableFailed,
            allowExternalProcessing: true
        )
        let processingFailure = OwnerTruthMediaTaskPresentation(
            mediaKind: .audio,
            fileName: "father.m4a",
            phase: .retryableFailed,
            allowExternalProcessing: true,
            sourceObjectID: sourceObjectID
        )
        let terminalProcessingFailure = OwnerTruthMediaTaskPresentation(
            mediaKind: .document,
            fileName: "notes.pdf",
            phase: .failed,
            allowExternalProcessing: false,
            sourceObjectID: sourceObjectID
        )
        let localOnlyVerified = OwnerTruthMediaTaskPresentation(
            mediaKind: .video,
            fileName: "family.mov",
            phase: .uploaded,
            allowExternalProcessing: false
        )

        XCTAssertEqual(uploadFailure.stateTitle, "云端文件未同步")
        XCTAssertEqual(uploadFailure.retryAction, .resumeUpload)
        XCTAssertEqual(uploadFailure.retryTitle, "重新上传")
        XCTAssertTrue(uploadFailure.detail.contains("本机"))

        XCTAssertEqual(processingFailure.stateTitle, "文件已同步，处理暂不可用")
        XCTAssertEqual(processingFailure.retryAction, .retryProcessing)
        XCTAssertEqual(processingFailure.retryTitle, "重新处理")
        XCTAssertTrue(processingFailure.detail.contains("无需重新选择文件"))

        XCTAssertEqual(terminalProcessingFailure.retryAction, .retryProcessing)
        XCTAssertEqual(localOnlyVerified.stateTitle, "文件已验证")
        XCTAssertTrue(localOnlyVerified.detail.contains("未请求外部 AI 处理"))
        XCTAssertFalse(localOnlyVerified.candidateHandoffAvailable)
    }

    @MainActor
    func testMediaTaskProcessingRetryUsesExistingSourceWithoutRepickingContent() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let rootURL = FileManager.default.temporaryDirectory
            .appendingPathComponent("owner-truth-media-processing-retry-\(UUID().uuidString)", isDirectory: true)
        defer {
            if FileManager.default.fileExists(atPath: rootURL.path) {
                try? FileManager.default.removeItem(at: rootURL)
            }
        }
        let secretStore = OwnerTruthMediaUploadSecretStoreSpy()
        let store = OwnerTruthMediaTaskStore(
            rootDirectory: rootURL,
            secretStore: secretStore,
            accountLeaseRuntime: runtime
        )
        let content = Data(repeating: 0x56, count: 128)
        let command = try OwnerTruthMediaUploadIntentCommand(
            expectedAuthorityEpoch: 0,
            mediaKind: .image,
            fileName: "family-photo.jpg",
            contentType: "image/jpeg",
            content: content,
            allowExternalProcessing: true
        )
        let sourceObjectID = recordID("00000000-0000-0000-0000-000000000b41")
        let token = try XCTUnwrap(
            OwnerTruthMediaUploadToken("one-time-owner-media-upload-token-000b41")
        )
        let prepared = try store.prepare(
            accountLease: lease,
            command: command,
            content: content
        )
        _ = try store.apply(
            uploadIntentReceipt: try mediaUploadIntentReceipt(
                vaultID: vaultID,
                command: command,
                sourceObjectID: sourceObjectID,
                token: token
            ),
            to: prepared.taskID,
            accountLease: lease
        )
        _ = try store.apply(
            sourceObjectResponse: try mediaSourceObjectResponse(
                vaultID: vaultID,
                command: command,
                sourceObjectID: sourceObjectID,
                state: .failed,
                processingStatus: .failed
            ),
            to: prepared.taskID,
            accountLease: lease
        )

        let client = OwnerTruthMediaCaptureClientSpy()
        client.retryResult = .success(try mediaSourceObjectResponse(
            vaultID: vaultID,
            command: command,
            sourceObjectID: sourceObjectID,
            state: .processing,
            processingStatus: .processing,
            status: .processingRequested
        ))
        let coordinator = OwnerTruthMediaTaskRecoveryCoordinator(
            store: store,
            client: client,
            accountLeaseRuntime: runtime
        )
        var retryResult: Result<Void, Error>?
        coordinator.retryProcessing(taskID: prepared.taskID, accountLease: lease) {
            retryResult = $0
        }

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { retryResult != nil })
        guard case .success? = retryResult else {
            return XCTFail("processing retry should succeed")
        }
        XCTAssertEqual(client.retryRequests, [sourceObjectID])
        XCTAssertEqual(
            try store.recoverableTasks(for: lease).first?.phase,
            .processing
        )
        XCTAssertThrowsError(try store.loadPendingContent(for: prepared.taskID, accountLease: lease))
    }

    func testMediaTaskStoreKeepsABATasksPartitionedAndRejectsOldLease() throws {
        let (runtime, firstLease) = try makeActiveRuntime()
        let rootURL = FileManager.default.temporaryDirectory
            .appendingPathComponent("owner-truth-media-aba-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: rootURL) }
        let secretStore = OwnerTruthMediaUploadSecretStoreSpy()
        let store = OwnerTruthMediaTaskStore(
            rootDirectory: rootURL,
            secretStore: secretStore,
            accountLeaseRuntime: runtime
        )
        let firstContent = Data(repeating: 0x43, count: 64)
        let firstCommand = try OwnerTruthMediaUploadIntentCommand(
            expectedAuthorityEpoch: 0,
            mediaKind: .document,
            fileName: "owner-a.txt",
            contentType: "text/plain",
            content: firstContent
        )
        let firstTask = try store.prepare(
            accountLease: firstLease,
            command: firstCommand,
            content: firstContent
        )

        runtime.publish(session: accountSession(
            subjectId: "owner-b",
            vaultId: "vault-b",
            generation: 2,
            generationID: UUID(uuidString: "00000000-0000-0000-0000-000000000202")!
        ))
        let secondLease = try XCTUnwrap(runtime.capture(forSubjectId: "owner-b"))
        XCTAssertEqual(try store.recoverableTasks(for: secondLease), [])
        XCTAssertThrowsError(
            try store.loadPendingContent(for: firstTask.taskID, accountLease: firstLease)
        ) { error in
            XCTAssertEqual(error as? OwnerTruthMediaTaskStoreError, .staleAccountLease)
        }

        let secondContent = Data(repeating: 0x44, count: 64)
        let secondTask = try store.prepare(
            accountLease: secondLease,
            command: OwnerTruthMediaUploadIntentCommand(
                expectedAuthorityEpoch: 0,
                mediaKind: .document,
                fileName: "owner-b.txt",
                contentType: "text/plain",
                content: secondContent
            ),
            content: secondContent
        )
        XCTAssertEqual(try store.recoverableTasks(for: secondLease).map(\.taskID), [secondTask.taskID])

        runtime.publish(session: accountSession(
            subjectId: "owner-a",
            vaultId: "vault-a",
            generation: 3,
            generationID: UUID(uuidString: "00000000-0000-0000-0000-000000000203")!
        ))
        let recoveredLease = try XCTUnwrap(runtime.capture(forSubjectId: "owner-a"))
        let recoveredTasks = try store.recoverableTasks(for: recoveredLease)
        XCTAssertEqual(recoveredTasks.map(\.taskID), [firstTask.taskID])
        XCTAssertEqual(
            try store.loadPendingContent(for: firstTask.taskID, accountLease: recoveredLease),
            firstContent
        )
        XCTAssertThrowsError(try store.recoverableTasks(for: secondLease)) { error in
            XCTAssertEqual(error as? OwnerTruthMediaTaskStoreError, .staleAccountLease)
        }
    }

    @MainActor
    func testNaturalInputProductReviewBatchAcknowledgementStaysHiddenWithoutPolicy() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let naturalInputClient = InterviewNaturalInputClientSpy()
        naturalInputClient.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        naturalInputClient.appendHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, append: command) }
        }
        naturalInputClient.endHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, end: command) }
        }
        naturalInputClient.continuationHandler = { _ in
            Result {
                let ended = naturalInputClient.endCommand != nil
                return try self.interviewNaturalInputContinuation(
                    vaultID: vaultID,
                    state: ended ? .reviewPending : .readyForNarrative,
                    canContinue: !ended,
                    canContinueLater: true
                )
            }
        }
        let controller = OwnerTruthInterviewNaturalInputViewController(
            accountLease: lease,
            client: naturalInputClient,
            accountLeaseRuntime: runtime,
            presentation: .product,
            guidedRecommendationPolicyAvailable: { false },
            lifeMapPolicyAvailable: { false },
            memorySearchPolicyAvailable: { false },
            interviewOutcomePolicyAvailable: { false },
            reviewBatchAcknowledgementPolicyAvailable: { false },
            qaGateEnabled: { true }
        )

        controller.loadViewIfNeeded()
        controller.submitQAFixture("没有发布权限时，不能开始整理。")
        let endButton = try XCTUnwrap(findView(
            in: controller.view,
            accessibilityIdentifier: "owner-truth-interview-natural-input-end"
