    private func candidateReleasePolicyPayload(
        version: String,
        revision: Int,
        expiresAt: String,
        enabled: Bool = true,
        audience: String = "owner",
        cohort: String = "authenticatedOwner"
    ) -> [String: Any] {
        [
            "schemaVersion": 1,
            "policyVersion": version,
            "policyRevision": revision,
            "issuedAt": "2025-01-01T00:00:00Z",
            "expiresAt": expiresAt,
            "minClient": 1,
            "emergencyRevision": 1,
            "audience": audience,
            "cohort": cohort,
            "source": "server",
            "shadowMode": false,
            "snapshotDecision": enabled ? "allow" : "deny",
            "features": [[
                "feature": DJFeature.ownerTruthCandidateReview.backendReleasePolicyFeature,
                "enabled": enabled,
                "releaseVisible": enabled,
                "audience": audience,
                "cohort": cohort,
                "requiredGates": ["G0"],
                "reason": enabled ? "candidateReviewEnabled" : "candidateReviewDisabled",
            ]],
        ]
    }

    private func saveCandidateReleasePolicy(
        _ payload: [String: Any],
        store: ReleasePolicyStore,
        scope: ReleasePolicyCacheScope
    ) throws {
        let formatter = ISO8601DateFormatter()
        let expiresAt = try XCTUnwrap(formatter.date(from: payload["expiresAt"] as? String ?? ""))
        let issuedAt = try XCTUnwrap(formatter.date(from: payload["issuedAt"] as? String ?? ""))
        try store.save(
            payload: JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys]),
            policySchemaVersion: payload["schemaVersion"] as? Int ?? 1,
            policyVersion: payload["policyVersion"] as? String ?? "candidate-test-policy",
            policyRevision: payload["policyRevision"] as? Int ?? 1,
            emergencyRevision: payload["emergencyRevision"] as? Int ?? 1,
            scope: scope,
            fetchedAt: issuedAt,
            expiresAt: expiresAt
        )
    }

    private func candidateReleasePolicyScope(
        lease: AccountLease,
        clientBuild: Int = FeatureGateService.shared.clientBuild
    ) -> ReleasePolicyCacheScope {
        ReleasePolicyCacheScope(
            accountUserId: lease.subjectId,
            appBuild: String(clientBuild),
            audience: "owner",
            cohort: "authenticatedOwner"
        )
    }

    private func makeCandidatePolicyTestClient(
        runtime: AccountLeaseRuntime,
        lease: AccountLease,
        authSession: @escaping () -> BackendAuthSessionContract?,
        authSessionRefresher: ((
            BackendAuthSessionContract,
            @escaping (BackendAuthSessionContract?) -> Void
        ) -> Void)? = nil,
        store: ReleasePolicyStore,
        policyTimeout: TimeInterval = 15,
        eventSink: @escaping (OwnerTruthCandidateInboxDiagnosticEvent) -> Void = { _ in }
    ) throws -> (
        client: DreamJourneyBackendClient,
        decision: (DJFeature) -> FeatureDecision,
        snapshot: () -> FeatureGatePolicySnapshot
    ) {
        let evaluator = FeatureGateEvaluator()
        let clientBuild = FeatureGateService.shared.clientBuild
        let scope = candidateReleasePolicyScope(lease: lease, clientBuild: clientBuild)
        let snapshot = {
            BackendCachedReleasePolicyEvaluation(
                cache: store.evaluate(scope: scope, risk: .ownerTextCore),
                risk: .ownerTextCore
            ).featureGatePolicySnapshot(for: .ownerTruthCandidateReview)
        }
        let decision: (DJFeature) -> FeatureDecision = { feature in
            evaluator.capture(
                feature: feature,
                risk: .ownerTextCore,
                purpose: .request,
                localEnabled: true,
                qaSyntheticOverride: false,
                accountGeneration: authSession()?.sessionId ?? "missing-session",
                policy: snapshot()
            )
        }
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: authSession,
            currentUserID: { authSession()?.userId },
            privateAccessAllowed: { true },
            featureDecision: decision,
            featureDecisionRevalidator: { captured in
                evaluator.revalidateForRequest(
                    captured: captured,
                    localEnabled: true,
                    accountGeneration: authSession()?.sessionId ?? "missing-session",
                    currentPolicy: snapshot()
                )
            },
            authSessionRefresher: authSessionRefresher,
            accountLeaseRuntime: runtime,
            releasePolicyStore: store,
            candidateInboxDiagnosticSink: eventSink,
            candidateInboxPolicyTimeout: policyTimeout
        )
        return (client, decision, snapshot)
    }

    private func waitForOwnerTruthHTTPUI(
        timeout: TimeInterval,
        until condition: @escaping () -> Bool
    ) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while !condition(), Date() < deadline {
            RunLoop.main.run(until: Date().addingTimeInterval(0.01))
        }
        return condition()
    }
}

private final class OwnerTruthReviewReadyHTTPURLProtocol: URLProtocol {
    typealias RequestHandler = (URLRequest, OwnerTruthReviewReadyHTTPURLProtocol) -> Void

    private static let lock = NSLock()
    private static var handler: RequestHandler?
    private static var requests: [URLRequest] = []
    private static var requestBodies: [Data?] = []

    static var recordedRequests: [URLRequest] {
        lock.lock()
        defer { lock.unlock() }
        return requests
    }

    static var recordedRequestBodies: [Data?] {
        lock.lock()
        defer { lock.unlock() }
        return requestBodies
    }

    static func install(handler: @escaping RequestHandler) {
        lock.lock()
        requests = []
        requestBodies = []
        self.handler = handler
        lock.unlock()
    }

    static func reset() {
        lock.lock()
        handler = nil
        requests = []
        requestBodies = []
        lock.unlock()
    }

    override class func canInit(with request: URLRequest) -> Bool {
        request.url?.host == "owner-truth.qa.invalid"
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest {
        request
    }

    override func startLoading() {
        let handler: RequestHandler?
        let body = Self.bodyData(from: request)
        Self.lock.lock()
        Self.requests.append(request)
        Self.requestBodies.append(body)
        handler = Self.handler
        Self.lock.unlock()

        guard let handler else {
            client?.urlProtocol(self, didFailWithError: URLError(.badServerResponse))
            return
        }
        handler(request, self)
    }

    override func stopLoading() {}

    private static func bodyData(from request: URLRequest) -> Data? {
        if let body = request.httpBody {
            return body
        }
        guard let stream = request.httpBodyStream else { return nil }
        stream.open()
        defer { stream.close() }
        var body = Data()
        var buffer = [UInt8](repeating: 0, count: 4_096)
        while stream.hasBytesAvailable {
            let count = stream.read(&buffer, maxLength: buffer.count)
            guard count >= 0 else { return nil }
            if count == 0 { break }
            body.append(buffer, count: count)
        }
        return body
    }

    func respond(statusCode: Int, body: Data) {
        guard let url = request.url,
              let response = HTTPURLResponse(
                url: url,
                statusCode: statusCode,
                httpVersion: "HTTP/1.1",
                headerFields: ["Content-Type": "application/json"]
              ) else {
            client?.urlProtocol(self, didFailWithError: URLError(.badServerResponse))
            return
        }
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: body)
        client?.urlProtocolDidFinishLoading(self)
    }

    func fail(_ error: Error) {
        client?.urlProtocol(self, didFailWithError: error)
    }
}

private final class OwnerTruthMediaUploadSecretStoreSpy: OwnerTruthMediaUploadSecretStoring {
    private var values: [String: OwnerTruthMediaUploadToken] = [:]

    func save(
        _ token: OwnerTruthMediaUploadToken,
        scopeDigest: String,
        taskID: UUID
    ) throws {
        values[key(scopeDigest: scopeDigest, taskID: taskID)] = token
    }

    func load(scopeDigest: String, taskID: UUID) throws -> OwnerTruthMediaUploadToken? {
        values[key(scopeDigest: scopeDigest, taskID: taskID)]
    }

    func remove(scopeDigest: String, taskID: UUID) throws {
        values.removeValue(forKey: key(scopeDigest: scopeDigest, taskID: taskID))
    }

    private func key(scopeDigest: String, taskID: UUID) -> String {
        "\(scopeDigest):\(taskID.uuidString.lowercased())"
    }
}

private final class OwnerTruthMediaCaptureClientSpy: OwnerTruthMediaCaptureClient {
    var createIntentResult: Result<OwnerTruthMediaUploadIntentReceipt, Error>?
    var uploadResult: Result<OwnerTruthMediaSourceObjectResponse, Error>?
    var defersUploadCompletion = false
    var fetchResult: Result<OwnerTruthMediaSourceObjectResponse, Error>?
    var retryResult: Result<OwnerTruthMediaSourceObjectResponse, Error>?
    var deletionResult: Result<OwnerTruthMediaDeletionReceipt, Error>?
    var deletionRetryResult: Result<OwnerTruthMediaDeletionReceipt, Error>?

    private(set) var uploadRequests: [(OwnerTruthRecordID, Data)] = []
    private(set) var fetchRequests: [OwnerTruthRecordID] = []
    private(set) var retryRequests: [OwnerTruthRecordID] = []
    private(set) var deletionRequests: [OwnerTruthRecordID] = []
    private(set) var deletionRetryRequests: [OwnerTruthRecordID] = []
    private var deferredUploadCompletion: ((Result<OwnerTruthMediaSourceObjectResponse, Error>) -> Void)?

    func createOwnerTruthMediaUploadIntent(
        accountLease: AccountLease,
        vaultID: OwnerTruthVaultID,
        command: OwnerTruthMediaUploadIntentCommand,
        completion: @escaping (Result<OwnerTruthMediaUploadIntentReceipt, Error>) -> Void
    ) {
        completion(createIntentResult ?? .failure(OwnerTruthMediaCaptureClientSpyError.missingResult))
    }

    func uploadOwnerTruthMediaContent(
        accountLease: AccountLease,
        vaultID: OwnerTruthVaultID,
        uploadIntentID: OwnerTruthRecordID,
        uploadToken: OwnerTruthMediaUploadToken,
        contentType: String,
        content: Data,
        completion: @escaping (Result<OwnerTruthMediaSourceObjectResponse, Error>) -> Void
    ) {
        uploadRequests.append((uploadIntentID, content))
        if defersUploadCompletion {
            deferredUploadCompletion = completion
            return
        }
        completion(uploadResult ?? .failure(OwnerTruthMediaCaptureClientSpyError.missingResult))
    }

    func completeDeferredUpload(with result: Result<OwnerTruthMediaSourceObjectResponse, Error>) {
        let completion = deferredUploadCompletion
        deferredUploadCompletion = nil
        completion?(result)
    }

    func fetchOwnerTruthMediaSourceObject(
        accountLease: AccountLease,
        vaultID: OwnerTruthVaultID,
        sourceObjectID: OwnerTruthRecordID,
        completion: @escaping (Result<OwnerTruthMediaSourceObjectResponse, Error>) -> Void
    ) {
        fetchRequests.append(sourceObjectID)
        completion(fetchResult ?? .failure(OwnerTruthMediaCaptureClientSpyError.missingResult))
    }

    func retryOwnerTruthMediaProcessing(
        accountLease: AccountLease,
        vaultID: OwnerTruthVaultID,
        sourceObjectID: OwnerTruthRecordID,
        completion: @escaping (Result<OwnerTruthMediaSourceObjectResponse, Error>) -> Void
    ) {
        retryRequests.append(sourceObjectID)
        completion(retryResult ?? .failure(OwnerTruthMediaCaptureClientSpyError.missingResult))
    }

    func requestOwnerTruthMediaDeletion(
        accountLease: AccountLease,
        vaultID: OwnerTruthVaultID,
        sourceObjectID: OwnerTruthRecordID,
        command: OwnerTruthMediaDeletionCommand,
        completion: @escaping (Result<OwnerTruthMediaDeletionReceipt, Error>) -> Void
    ) {
        deletionRequests.append(sourceObjectID)
        completion(deletionResult ?? .failure(OwnerTruthMediaCaptureClientSpyError.missingResult))
    }

    func retryOwnerTruthMediaDeletion(
        accountLease: AccountLease,
        vaultID: OwnerTruthVaultID,
        sourceObjectID: OwnerTruthRecordID,
        command: OwnerTruthMediaDeletionCommand,
